//! Port of `Models/OnThisDay.cs` and `Models/OnThisDayJsonSerializerContext.cs`: the events of
//! the "On this day" feed of the Wikimedia API and the articles of their pages, read from the
//! JSON of the feed.
//!
//! The serializer context of the reference (generated by the JSON source generator with
//! `PropertyNameCaseInsensitive = true`) is [`OnThisDayJsonSerializerContext`]: the records
//! derive `serde`'s deserialization, and the property names of the document are matched
//! without regard to their case.

use super::WikipediaHttpClient;
use ferroui_base::data::model::{Event, INotifyPropertyChanged};
use ferroui_base::ferro_markup_type;
use ferroui_base::media::imaging::Bitmap;
use ferroui_base::media::IImage;
use mini_mvvm::ViewModelBase;
use serde::Deserialize;
use std::cell::{Cell, RefCell};
use std::rc::Rc;

/// `OnThisDay`: the selected events of a day.
#[derive(Default, Deserialize)]
pub struct OnThisDay {
    pub selected: Option<Vec<OnThisDayEvent>>,
}

/// `OnThisDayEvent`: an event, its year and the articles about it.
#[derive(Default, Deserialize)]
pub struct OnThisDayEvent {
    pub text: Option<String>,
    // A missing year is the default of the reference's `int`.
    #[serde(default)]
    pub year: i32,
    pub pages: Option<Vec<OnThisDayArticle>>,
}

/// `OnThisDayArticle`: an article of an event, the model of a row of the Wikipedia page. Its
/// image is the thumbnail of the article, downloaded when the image is first read.
#[derive(Default, Deserialize)]
#[serde(default)]
pub struct OnThisDayArticle {
    #[serde(skip)]
    base: ViewModelBase,
    #[serde(skip)]
    loaded_image: Cell<bool>,
    #[serde(skip)]
    image: RefCell<Option<Rc<Bitmap>>>,
    r#type: RefCell<Option<String>>,
    titles: RefCell<Option<OnThisDayTitles>>,
    thumbnail: RefCell<Option<OnThisDayImage>>,
    description: RefCell<Option<String>>,
    extract: RefCell<Option<String>>,
}

impl PartialEq for OnThisDayArticle {
    fn eq(&self, other: &Self) -> bool {
        std::ptr::eq(self, other)
    }
}

impl INotifyPropertyChanged for OnThisDayArticle {
    fn property_changed(&self) -> &Event<str> {
        self.base.property_changed()
    }
}

impl OnThisDayArticle {
    pub fn new() -> Rc<Self> {
        Rc::new(Self::default())
    }

    pub fn r#type(&self) -> Option<String> {
        self.r#type.borrow().clone()
    }

    pub fn set_type(&self, value: Option<String>) {
        *self.r#type.borrow_mut() = value;
    }

    pub fn titles(&self) -> Option<OnThisDayTitles> {
        self.titles.borrow().clone()
    }

    pub fn set_titles(&self, value: Option<OnThisDayTitles>) {
        *self.titles.borrow_mut() = value;
    }

    pub fn thumbnail(&self) -> Option<OnThisDayImage> {
        self.thumbnail.borrow().clone()
    }

    pub fn set_thumbnail(&self, value: Option<OnThisDayImage>) {
        *self.thumbnail.borrow_mut() = value;
    }

    pub fn description(&self) -> Option<String> {
        self.description.borrow().clone()
    }

    pub fn set_description(&self, value: Option<String>) {
        *self.description.borrow_mut() = value;
    }

    pub fn extract(&self) -> Option<String> {
        self.extract.borrow().clone()
    }

    pub fn set_extract(&self, value: Option<String>) {
        *self.extract.borrow_mut() = value;
    }

    /// `Image`: the thumbnail of the article. The first read starts the download of the
    /// thumbnail and returns no image; the property changes when the image arrives.
    pub fn image(self: &Rc<Self>) -> Option<Rc<Bitmap>> {
        if self.image.borrow().is_none() && !self.loaded_image.get() {
            self.load_image_async();
        }

        self.image.borrow().clone()
    }

    fn set_image(&self, value: Option<Rc<Bitmap>>) {
        // A bitmap has no equality: the notification compares the handles.
        let changed = match (&*self.image.borrow(), &value) {
            (None, None) => false,
            (Some(a), Some(b)) => !Rc::ptr_eq(a, b),
            _ => true,
        };
        if changed {
            *self.image.borrow_mut() = value;
            self.base.raise_property_changed("Image");
        }
    }

    fn load_image_async(self: &Rc<Self>) {
        self.loaded_image.set(true);

        let Some(source) = self.thumbnail.borrow().as_ref().and_then(|thumbnail| thumbnail.source.clone()) else {
            return;
        };

        // Load the image from the url.
        let this = Rc::downgrade(self);
        WikipediaHttpClient::shared().get_byte_array_async(source, move |bytes| {
            // A thumbnail that cannot be downloaded or decoded leaves the article without an
            // image (the reference ignores every exception).
            let Ok(bytes) = bytes else {
                return;
            };
            let Ok(bitmap) = Bitmap::from_stream(&mut std::io::Cursor::new(bytes)) else {
                return;
            };
            if let Some(this) = this.upgrade() {
                this.set_image(Some(Rc::new(bitmap)));
            }
        });
    }
}

/// `OnThisDayTitles`: the titles of an article.
#[derive(Clone, Debug, Default, Deserialize, PartialEq, Eq)]
pub struct OnThisDayTitles {
    pub normalized: Option<String>,
}

/// `OnThisDayImage`: an image of an article: its URL and its size.
#[derive(Clone, Debug, Default, Deserialize, PartialEq, Eq)]
pub struct OnThisDayImage {
    pub source: Option<String>,
    #[serde(default)]
    pub width: i32,
    #[serde(default)]
    pub height: i32,
}

/// `OnThisDayJsonSerializerContext`: reads the JSON of the feed with
/// `PropertyNameCaseInsensitive = true`.
pub struct OnThisDayJsonSerializerContext;

impl OnThisDayJsonSerializerContext {
    /// `JsonSerializer.Deserialize(s, OnThisDayJsonSerializerContext.Default.OnThisDay)`: the
    /// day the document `text` describes; `None` for the document `null`.
    ///
    /// The property names of the document are matched without regard to their case: they are
    /// lowered before the records read them (every property of the records is one lowercase
    /// word). Properties the records do not have are ignored.
    pub fn deserialize_on_this_day(text: &str) -> Result<Option<OnThisDay>, serde_json::Error> {
        let mut document: serde_json::Value = serde_json::from_str(text)?;
        lower_property_names(&mut document);
        serde_json::from_value(document)
    }
}

/// Lowers the names of the properties of the objects of `value`, at every depth.
fn lower_property_names(value: &mut serde_json::Value) {
    match value {
        serde_json::Value::Object(properties) => {
            for (name, mut property) in std::mem::take(properties) {
                lower_property_names(&mut property);
                properties.insert(name.to_lowercase(), property);
            }
        }
        serde_json::Value::Array(items) => items.iter_mut().for_each(lower_property_names),
        _ => {}
    }
}

ferro_markup_type!(class OnThisDayArticle {
    this: Rc<OnThisDayArticle>,
    handles: [OnThisDayArticle, Rc<OnThisDayArticle>, Option<Rc<OnThisDayArticle>>],
    constructors: [() => OnThisDayArticle::new],
    properties: [
        Type: Option<String> {
            get: |this: &Rc<OnThisDayArticle>| this.r#type(),
            set: |this: &Rc<OnThisDayArticle>, value: Option<String>| this.set_type(value)
        },
        Description: Option<String> {
            get: |this: &Rc<OnThisDayArticle>| this.description(),
            set: |this: &Rc<OnThisDayArticle>, value: Option<String>| this.set_description(value)
        },
        Extract: Option<String> {
            get: |this: &Rc<OnThisDayArticle>| this.extract(),
            set: |this: &Rc<OnThisDayArticle>, value: Option<String>| this.set_extract(value)
        },
        // Declared with the contract of the bitmap: a bitmap handle has no equality and cannot
        // be the type of a declared property.
        Image: Option<Rc<dyn IImage>> {
            get: |this: &Rc<OnThisDayArticle>| this.image().map(|image| image as Rc<dyn IImage>)
        },
    ],
    notify_property_changed: OnThisDayArticle,
});

#[cfg(test)]
mod tests {
    // Not ports: the reference has no tests of its records.
    use super::*;

    #[test]
    fn the_property_names_are_matched_in_any_case() {
        let day = OnThisDayJsonSerializerContext::deserialize_on_this_day(
            r#"{ "Selected": [ { "TEXT": "An event", "Year": 2026, "pages": [ { "Titles": { "Normalized": "A page" }, "EXTRACT": "An extract" } ] } ] }"#,
        )
        .unwrap()
        .unwrap();

        let selected = day.selected.unwrap();
        assert_eq!(1, selected.len());
        assert_eq!(Some("An event".to_string()), selected[0].text);
        assert_eq!(2026, selected[0].year);
        let pages = selected[0].pages.as_ref().unwrap();
        assert_eq!(Some("A page".to_string()), pages[0].titles().and_then(|titles| titles.normalized));
        assert_eq!(Some("An extract".to_string()), pages[0].extract());
    }

    #[test]
    fn the_document_null_is_no_day() {
        assert!(OnThisDayJsonSerializerContext::deserialize_on_this_day("null").unwrap().is_none());
    }

    #[test]
    fn missing_properties_have_their_defaults_and_unknown_ones_are_ignored() {
        let day = OnThisDayJsonSerializerContext::deserialize_on_this_day(r#"{ "selected": [ { "unknown": 1 } ], "births": [] }"#)
            .unwrap()
            .unwrap();

        let selected = day.selected.unwrap();
        assert_eq!(None, selected[0].text);
        assert_eq!(0, selected[0].year);
        assert!(selected[0].pages.is_none());
    }

    #[test]
    fn an_article_without_a_thumbnail_has_no_image() {
        let article = OnThisDayArticle::new();

        assert!(article.image().is_none());
        assert!(article.image().is_none());
    }
}
